const { chromium } = require('playwright');

const casos = {
  'bloques hermanos (30 y 20)': '<div class="s" style="margin-bottom:30px"></div><div class="s" style="margin-top:20px"></div>',
  'uno es inline-block':        '<div class="s" style="margin-bottom:30px"></div><div class="s" style="margin-top:20px;display:inline-block;width:50px;vertical-align:top"></div>',
  'dentro de un contenedor flex': '<div style="display:flex;flex-direction:column"><div class="s" style="margin-bottom:30px"></div><div class="s" style="margin-top:20px"></div></div>',
  'margen negativo (30 y -10)': '<div class="s" style="margin-bottom:30px"></div><div class="s" style="margin-top:-10px"></div>',
};

(async () => {
  const nav = await chromium.launch({ args: ['--no-sandbox'] });
  const pag = await nav.newPage({ viewport: { width: 800, height: 600 } });
  for (const [nombre, html] of Object.entries(casos)) {
    await pag.setContent(`<!doctype html><style>body{margin:0} .s{height:50px}</style>${html}`);
    const ys = await pag.$$eval('.s', xs => xs.map(x => x.getBoundingClientRect().y));
    console.log(nombre.padEnd(32), 'espacio entre las dos cajas =', ys[1] - ys[0] - 50);
  }
  // un hijo con margen superior de 40px dentro de una sección
  for (const [nombre, estilo] of [['sin borde ni relleno', ''], ['con borde arriba de 1px', 'border-top:1px solid'], ['con display:flow-root', 'display:flow-root']]) {
    await pag.setContent(`<!doctype html><style>body{margin:0}</style><section style="${estilo}"><div style="height:50px;margin-top:40px"></div></section>`);
    const y = await pag.$eval('section', s => s.getBoundingClientRect().y);
    console.log(('sección ' + nombre).padEnd(32), 'la sección empieza en y =', y);
  }
  await nav.close();
})();

