const { chromium } = require('playwright');

(async () => {
  const nav = await chromium.launch({ args: ['--no-sandbox'], ignoreDefaultArgs: ['--hide-scrollbars'] });
  const pag = await nav.newPage({ viewport: { width: 800, height: 600 } });
  const caja = async (html, id = 'x') => {
    await pag.setContent(`<!doctype html><style>body{margin:0;font:16px sans-serif}</style>${html}`);
    return pag.$eval('#' + id, e => { const r = e.getBoundingClientRect(); return `${r.width} x ${r.height}`; });
  };
  console.log('10rem x 2rem, raíz por defecto :', await caja('<div id="x" style="width:10rem;height:2rem"></div>'));
  console.log('10rem x 2rem, html a 125%      :', await caja('<style>html{font-size:125%}</style><div id="x" style="width:10rem;height:2rem"></div>'));
  console.log('160px x 32px, html a 125%      :', await caja('<style>html{font-size:125%}</style><div id="x" style="width:160px;height:32px"></div>'));
  console.log('10em en tres niveles de 1.5em  :', await caja('<div style="font-size:1.5em"><div style="font-size:1.5em"><div id="x" style="font-size:1.5em;width:10em;height:1em"></div></div></div>'));
  console.log('width 50%, padding-top 25%     :', await caja('<div style="width:400px;height:300px"><div id="x" style="width:50%;height:50%;padding-top:25%"></div></div>'));
  console.log('height 50%, padre sin altura   :', await caja('<div style="width:400px"><div id="x" style="width:50%;height:50%"></div></div>'));
  console.log('botón 16px, padding .5em 1em   :', await caja('<button id="x" style="font-size:16px;padding:.5em 1em;border:0">Pagar</button>'));
  console.log('botón 32px, padding .5em 1em   :', await caja('<button id="x" style="font-size:32px;padding:.5em 1em;border:0">Pagar</button>'));
  console.log('50vw x 50vh                    :', await caja('<div id="x" style="width:50vw;height:50vh"></div>'));
  console.log('10ch                           :', await caja('<div id="x" style="width:10ch"></div>'));
  await pag.setContent('<!doctype html><style>body{margin:0}</style><div style="height:2000px"></div><div id="x" style="width:100vw;height:10px"></div>');
  console.log('100vw con barra de scroll      :', await pag.evaluate(() => {
    const h = document.documentElement;
    return `ventana=${innerWidth}, área útil=${h.clientWidth}, ancho del contenido=${h.scrollWidth}`;
  }));
  const tel = await nav.newContext({ viewport: { width: 390, height: 664 }, isMobile: true, deviceScaleFactor: 3 });
  const m = await tel.newPage();
  await m.setContent('<!doctype html><meta name="viewport" content="width=device-width"><style>body{margin:0}</style><div id="a" style="height:100vh"></div><div id="b" style="height:100svh"></div><div id="c" style="height:100lvh"></div><div id="d" style="height:100dvh"></div>');
  console.log('teléfono emulado, alto de 100vh/svh/lvh/dvh :', await m.evaluate(() => ['a', 'b', 'c', 'd'].map(i => document.getElementById(i).getBoundingClientRect().height).join(' / ')));
  console.log('teléfono emulado, píxeles CSS y físicos :', await m.evaluate(() => `${innerWidth} px CSS de ancho x ${devicePixelRatio} = ${innerWidth * devicePixelRatio} px físicos`));
  await nav.close();
})();
